## Corrected Implementation

*The ants have processed this extensively.*

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    ready     chan struct{} // Signals when loading completes
    err       error         // Stores load error for waiters
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data   map[string]*CacheEntry
    mu     sync.RWMutex
    ttl    time.Duration
    loader LoadFunc
    stats  Stats
}

type Stats struct {
    Hits       int64
    Misses     int64
    LoadErrors int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Check cache with read lock
    c.mu.RLock()
    entry, ok := c.data[key]
    if ok && time.Now().Before(entry.ExpiresAt) && entry.ready != nil {
        select {
        case <-entry.ready:
            // Entry is ready
            c.mu.RUnlock()
            if entry.err != nil {
                return nil, entry.err
            }
            atomic.AddInt64(&c.stats.Hits, 1)
            return entry.Value, nil
        default:
            // Still loading, wait outside lock
        }
    }
    c.mu.RUnlock()

    // Need to load - acquire write lock
    c.mu.Lock()

    // Double-check
    entry, ok = c.data[key]
    if ok && time.Now().Before(entry.ExpiresAt) {
        c.mu.Unlock()
        // Wait for loading to complete
        select {
        case <-entry.ready:
            if entry.err != nil {
                return nil, entry.err
            }
            atomic.AddInt64(&c.stats.Hits, 1)
            return entry.Value, nil
        case <-ctx.Done():
            return nil, ctx.Err()
        }
    }

    // Create loading entry
    entry = &CacheEntry{
        ExpiresAt: time.Now().Add(c.ttl),
        ready:     make(chan struct{}),
    }
    c.data[key] = entry
    c.mu.Unlock()

    atomic.AddInt64(&c.stats.Misses, 1)

    // Load outside lock
    value, err := c.loader(ctx, key)

    c.mu.Lock()
    if err != nil {
        atomic.AddInt64(&c.stats.LoadErrors, 1)
        entry.err = err
        delete(c.data, key)
    } else {
        entry.Value = value
    }
    close(entry.ready) // Signal all waiters
    c.mu.Unlock()

    if err != nil {
        return nil, err
    }
    return value, nil
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()

    ready := make(chan struct{})
    close(ready)
    c.data[key] = &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
        ready:     ready,
    }
}

func (c *Cache) Invalidate(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()
    delete(c.data, key)
}

func (c *Cache) InvalidateAll() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data = make(map[string]*CacheEntry)
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            value, err := c.Get(ctx, k)
            if err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }

    wg.Wait()
    return results
}

func (c *Cache) cleanupLoop() {
    ticker := time.NewTicker(time.Minute)
    defer ticker.Stop()
    for range ticker.C {
        c.cleanup()
    }
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()

    now := time.Now()
    for key, entry := range c.data {
        select {
        case <-entry.ready:
            if now.After(entry.ExpiresAt) {
                delete(c.data, key)
            }
        default:
            // Still loading, don't delete
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}

func (c *Cache) GetStats() Stats {
    return Stats{
        Hits:       atomic.LoadInt64(&c.stats.Hits),
        Misses:     atomic.LoadInt64(&c.stats.Misses),
        LoadErrors: atomic.LoadInt64(&c.stats.LoadErrors),
    }
}
```

